CREATE TYPE "Role" AS ENUM ('ADMIN','WAITER','KITCHEN');
CREATE TABLE "Restaurant" ("id" SERIAL PRIMARY KEY,"slug" TEXT NOT NULL UNIQUE,"name" TEXT NOT NULL,"tagline" TEXT,"accent" TEXT NOT NULL DEFAULT '#E4A15D',"phone" TEXT,"address" TEXT,"hours" TEXT,"hero" TEXT,"logo" TEXT,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "RestaurantSettings" ("id" SERIAL PRIMARY KEY,"restaurantId" INTEGER NOT NULL UNIQUE,"currency" TEXT NOT NULL DEFAULT 'KM',"language" TEXT NOT NULL DEFAULT 'bs',"timezone" TEXT NOT NULL DEFAULT 'Europe/Sarajevo',"reservationEnabled" BOOLEAN NOT NULL DEFAULT true,"qrOrderingEnabled" BOOLEAN NOT NULL DEFAULT true,CONSTRAINT "RestaurantSettings_restaurantId_fkey" FOREIGN KEY ("restaurantId") REFERENCES "Restaurant"("id") ON DELETE CASCADE);
CREATE TABLE "User" ("id" SERIAL PRIMARY KEY,"restaurantId" INTEGER NOT NULL,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"role" "Role" NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "User_restaurantId_fkey" FOREIGN KEY ("restaurantId") REFERENCES "Restaurant"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "User_restaurantId_email_key" ON "User"("restaurantId","email");
CREATE TABLE "RestaurantTable" ("id" SERIAL PRIMARY KEY,"restaurantId" INTEGER NOT NULL,"name" TEXT NOT NULL,"zone" TEXT NOT NULL DEFAULT 'SALA',"capacity" INTEGER NOT NULL DEFAULT 4,"status" TEXT NOT NULL DEFAULT 'SLOBODAN',"x" INTEGER NOT NULL DEFAULT 80,"y" INTEGER NOT NULL DEFAULT 80,"shape" TEXT NOT NULL DEFAULT 'square',CONSTRAINT "RestaurantTable_restaurantId_fkey" FOREIGN KEY ("restaurantId") REFERENCES "Restaurant"("id") ON DELETE CASCADE);
CREATE TABLE "MenuCategory" ("id" SERIAL PRIMARY KEY,"restaurantId" INTEGER NOT NULL,"name" TEXT NOT NULL,"sortOrder" INTEGER NOT NULL DEFAULT 0,"visible" BOOLEAN NOT NULL DEFAULT true,CONSTRAINT "MenuCategory_restaurantId_fkey" FOREIGN KEY ("restaurantId") REFERENCES "Restaurant"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "MenuCategory_restaurantId_name_key" ON "MenuCategory"("restaurantId","name");
CREATE TABLE "MenuItem" ("id" SERIAL PRIMARY KEY,"restaurantId" INTEGER NOT NULL,"categoryId" INTEGER,"name" TEXT NOT NULL,"description" TEXT,"price" DECIMAL(10,2) NOT NULL,"visible" BOOLEAN NOT NULL DEFAULT true,"sortOrder" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "MenuItem_restaurantId_fkey" FOREIGN KEY ("restaurantId") REFERENCES "Restaurant"("id") ON DELETE CASCADE,CONSTRAINT "MenuItem_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "MenuCategory"("id") ON DELETE SET NULL);
CREATE TABLE "Reservation" ("id" SERIAL PRIMARY KEY,"restaurantId" INTEGER NOT NULL,"name" TEXT NOT NULL,"phone" TEXT NOT NULL,"date" TEXT NOT NULL,"time" TEXT NOT NULL,"guests" INTEGER NOT NULL,"zone" TEXT,"message" TEXT,"status" TEXT NOT NULL DEFAULT 'NA ČEKANJU',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Reservation_restaurantId_fkey" FOREIGN KEY ("restaurantId") REFERENCES "Restaurant"("id") ON DELETE CASCADE);
CREATE TABLE "Order" ("id" SERIAL PRIMARY KEY,"restaurantId" INTEGER NOT NULL,"tableId" INTEGER NOT NULL,"source" TEXT NOT NULL DEFAULT 'WAITER',"status" TEXT NOT NULL DEFAULT 'NOVA',"note" TEXT,"total" DECIMAL(10,2) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"paidAt" TIMESTAMP(3),CONSTRAINT "Order_restaurantId_fkey" FOREIGN KEY ("restaurantId") REFERENCES "Restaurant"("id") ON DELETE CASCADE,CONSTRAINT "Order_tableId_fkey" FOREIGN KEY ("tableId") REFERENCES "RestaurantTable"("id") ON DELETE RESTRICT);
CREATE TABLE "OrderItem" ("id" SERIAL PRIMARY KEY,"orderId" INTEGER NOT NULL,"menuItemId" INTEGER,"name" TEXT NOT NULL,"price" DECIMAL(10,2) NOT NULL,"qty" INTEGER NOT NULL,CONSTRAINT "OrderItem_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "Order"("id") ON DELETE CASCADE,CONSTRAINT "OrderItem_menuItemId_fkey" FOREIGN KEY ("menuItemId") REFERENCES "MenuItem"("id") ON DELETE SET NULL);
CREATE TABLE "Payment" ("id" SERIAL PRIMARY KEY,"orderId" INTEGER NOT NULL UNIQUE,"amount" DECIMAL(10,2) NOT NULL,"method" TEXT NOT NULL DEFAULT 'CASH',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Payment_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "Order"("id") ON DELETE CASCADE);
CREATE TABLE "Notification" ("id" SERIAL PRIMARY KEY,"restaurantId" INTEGER NOT NULL,"text" TEXT NOT NULL,"type" TEXT NOT NULL DEFAULT 'info',"read" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Notification_restaurantId_fkey" FOREIGN KEY ("restaurantId") REFERENCES "Restaurant"("id") ON DELETE CASCADE);
CREATE TABLE "AuditLog" ("id" SERIAL PRIMARY KEY,"restaurantId" INTEGER NOT NULL,"userId" INTEGER,"action" TEXT NOT NULL,"entity" TEXT,"entityId" TEXT,"meta" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AuditLog_restaurantId_fkey" FOREIGN KEY ("restaurantId") REFERENCES "Restaurant"("id") ON DELETE CASCADE);
CREATE INDEX "RestaurantTable_restaurantId_status_idx" ON "RestaurantTable"("restaurantId","status");
CREATE INDEX "MenuItem_restaurantId_visible_idx" ON "MenuItem"("restaurantId","visible");
CREATE INDEX "Reservation_restaurantId_date_status_idx" ON "Reservation"("restaurantId","date","status");
CREATE INDEX "Order_restaurantId_status_createdAt_idx" ON "Order"("restaurantId","status","createdAt");
CREATE INDEX "Notification_restaurantId_read_createdAt_idx" ON "Notification"("restaurantId","read","createdAt");
CREATE INDEX "AuditLog_restaurantId_createdAt_idx" ON "AuditLog"("restaurantId","createdAt");
